-- 0023_linzzy_products_strict_drive_text: the Linzzy product rows use Lexta's own words, sentence for sentence.
--
-- Why: the strict source sweep (Desmond, 17 November 2026: only the Drive and the current linzzyproducts.com, nothing
-- 1773 wrote) changed apps/linzzy/content/catalogue.ts so every product line quotes docs/content/linzzy/products.md.
-- The card summary (short_description) written by 0016 was 1773's own one line summary; it is now the sentence of
-- Lexta's description that names the product. The other four text columns are rewritten from the same catalogue so the
-- database and the site's fallback match exactly (they already carry Lexta's words). Generated from the catalogue.
--
-- Only the six Linzzy Drive rows, only these five columns. Rows staff have saved in Product Management are never
-- overwritten ("updated_by is null"). Idempotent. RLS unchanged. Not applied: Desmond applies it.
update public.products p
set short_description = v.short_description,
    long_description = v.long_description,
    key_features = v.key_features,
    usage_instructions = v.usage_instructions,
    ingredients = v.ingredients
from public.brands b,
  (values
  ('heavy-flow-sanitary-towels', 'Linzzy Heavy Flow Sanitary Towels are designed for women who prefer higher absorbency during heavier menstrual flow.', 'Some menstrual days require additional protection. Linzzy Heavy Flow Sanitary Towels are designed for women who prefer higher absorbency during heavier menstrual flow. Featuring the brand''s Absorb, Lock and Breathe design positioning, this variant offers a practical option for managing heavier days while supporting everyday comfort.', array['Higher-absorbency menstrual protection', '290 mm towel length', 'Designed for heavier-flow days', 'Includes complimentary panty liners', 'Comfort-focused design']::text[], 'Remove the individual wrapper, peel away the adhesive backing and position the towel securely inside clean underwear. Change regularly and whenever saturated.', null),
  ('cool-mint-sanitary-towels', 'Linzzy Cool Mint Sanitary Towels provide a cooling-style option within the feminine care collection.', 'Every woman has different preferences when it comes to menstrual care. Linzzy Cool Mint Sanitary Towels provide a cooling-style option within the feminine care collection. The pack combines sanitary towels of different lengths, allowing consumers to choose according to their flow and coverage preferences.', array['Cool Mint variant', 'Two sanitary towel lengths', 'Panty liners included', 'Absorb, Lock and Breathe design positioning', 'Convenient mixed-length pack']::text[], 'Position the towel securely inside clean underwear and change regularly according to your menstrual flow.', null),
  ('extra-long-sanitary-towels', 'Linzzy Extra Long Sanitary Towels offer an extended-length option for consumers who prefer additional coverage.', 'Whether you''re resting, travelling or managing a busy day, choosing a sanitary towel with suitable coverage can make a difference. Linzzy Extra Long Sanitary Towels offer an extended-length option for consumers who prefer additional coverage.', array['Extended 330 mm coverage', 'Additional 290 mm towels', 'Complimentary panty liners', 'Designed for consumers who prefer longer towels', 'Comfort-focused design']::text[], 'Centre the towel inside clean underwear, secure the adhesive and ensure the product sits comfortably.', null),
  ('panty-liners', 'Linzzy Panty Liners offer a compact option for managing light spotting or small amounts of moisture.', 'Sometimes, the smallest essentials make everyday routines more convenient. Linzzy Panty Liners offer a compact option for managing light spotting or small amounts of moisture. Designed for light protection rather than regular menstrual flow, these liners can be incorporated into personal care routines according to individual preference.', array['Compact 155 mm design', '30 liners per pack', 'Suitable for light spotting and small amounts of moisture', 'Convenient everyday care option']::text[], 'Attach the liner securely inside clean underwear. Replace when damp or soiled.', null),
  ('baby-diapers', 'Linzzy Baby Diapers feature a flexible-comfort design intended to support everyday diapering needs.', 'Every baby has a world to discover. From stretching little legs to learning how to crawl, babies need diapers that fit comfortably and allow natural movement. Linzzy Baby Diapers feature a flexible-comfort design intended to support everyday diapering needs.', array['Flexible Comfort design', 'Unisex diaper range', 'Different sizes for growing babies', 'Disposable diaper format', 'Designed for everyday baby care']::text[], 'Place your baby on a clean, safe changing surface. Remove the soiled diaper and gently clean the diaper area. Allow the skin to dry. Position a fresh Linzzy diaper comfortably. Fasten securely without making it too tight. Dispose of the used diaper responsibly and wash your hands.', null),
  ('baby-wipes', 'Linzzy Baby Wipes offer a convenient cleaning option for everyday care routines at home or on the go.', 'Little hands, tiny feet and unexpected messes are all part of raising a baby. Linzzy Baby Wipes offer a convenient cleaning option for everyday care routines at home or on the go. Available in different variants, Linzzy Baby Wipes provide parents with options to suit their preferences.', array['Convenient resealable packaging', '80 wipes per pack', 'Different product variants', 'Suitable for everyday external cleaning, subject to label directions', 'Portable for diaper bags and travel']::text[], 'Open the resealable lid. Remove a wipe with clean hands. Gently clean the intended external skin area. Use additional wipes when necessary to avoid spreading dirt. Close the packaging securely after use. Dispose of used wipes in an appropriate waste bin.', '[PLACEHOLDER: complete ingredient list for each wipes variant, from Lexta]')
  ) as v(slug, short_description, long_description, key_features, usage_instructions, ingredients)
where b.id = p.brand_id and b.slug = 'linzzy' and p.slug = v.slug and p.updated_by is null;
